			for (let j = 0; j < foods.length; j++) {
				let food = foods[j];
				let fLoc = food.location.copy();
				let bLoc = fish.location.copy();
				let d = bLoc.dist(fLoc);
				if (d < 100.0) {
					fish.arrive(fLoc);
					if (fish.hasArrive === true) {
						food.isDead = true;
						fish.hasArrive = false;
					}
					fish.wander();
				}
			}
		}
		//*/

	}

	if (randomNumber <= 6) {
		let foodLocation = createVector(random(100, width - 100), random(100, height - 100));
		let food = new Food(foodLocation);
		foods.push(food);
	}

	for (let i = foods.length - 1; i >= 0; i--) {
		let food = foods[i];
		if (!food.getIsDead()) {
			food.update();
			food.render();
			if (myFishAteFood(food)) {
				foods.splice(i, 1);
			}
		} else {
			foods.splice(i, 1);
		}
	}

	// Create a new ripple at a random position at intervals
    if (frameCount % 20 === 0) {
        let ripple = {
            x: random(width),
            y: random(height),
            radius: 0,
            speed: 2,
            maxRadius: 100
        };
        ripples.push(ripple);
    }

    // Update and draw ripples
    for (let i = ripples.length - 1; i >= 0; i--) {
        let r = ripples[i];
        stroke(`rgba(198, 217, 236, ${1 - r.radius / r.maxRadius})`); // Nice color with fading effect
        push();
			  noFill();
				ellipse(r.x, r.y, r.radius * 2);
				pop();
        r.radius += r.speed;

        // Remove the ripple if it exceeds maxRadius
        if (r.radius > r.maxRadius) {
            ripples.splice(i, 1);
        }
    }

}

function myFishAteFood(food) {
	let foodEaten = false;

	let distanceToFood = p5.Vector.sub(myFish.getLocation(), food.getLocation()).mag();
	if (distanceToFood < 10) {
		foodEaten = true;
		gulp.play(); // Uncomment if you have a gulp sound to play
		myFish.setBodySizeH(myFish.getBodySizeH() * 1.1);
		myFish.setBodySizeW(myFish.getBodySizeW() * 1.1);
		myFish.setLastAteTimer(int(frameRate() / 2));
		myFish.setFoodEaten(myFish.getFoodEaten() + 1);
	}

	return foodEaten;
}

function mouseMoved() {
	let mousePosition = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	myFish.setMousePosition(mousePosition);
}

function touchMoved() {
	let mousePosition = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	myFish.setMousePosition(mousePosition);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}

